 result['files'].append({'path':name,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'source':str(path),'snapshot':'prefix of possibly growing live file'})
for name in ['23973.out','23973.err']:
 path=root/'runs'/name;data=path.read_bytes();(live/name).write_bytes(data)
 result['files'].append({'path':name,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'source':str(path),'snapshot':'prefix of possibly growing live file'})
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
