entry=next(a for a in registry['entries'] if a['id']=='s10-combo-repeat1-n52')
for name,expected in entry['payload_sha256'].items():
 result['payload'][name]={'submitted_matches_registry':sha(run/'submitted'/name)==expected,'submitted_matches_frozen_bundle':sha(run/'submitted'/name)==sha(bundle/name)}
result['execution_vs_23904']={name:sha(run/'submitted'/name)==sha(source/'submitted'/name) for name in entry['payload_sha256'] if name not in ['config.json','job.sbatch']}
