 if role=='decode-0':
  result['runtime'][role].update(mnnvl_ranks=sorted({int(n) for n in re.findall(r'backend=mnnvl, rank=(\\d+), world_size=8',text)}),flashinfer_decode_ranks=sorted({int(n) for n in re.findall(r'TP(\\d+) EP\\d+\\] Using hybrid attention backend.*decode_backend=flashinfer, prefill_backend=fa3',text)}),nixl_ucx_ranks=sorted({int(n) for n in re.findall(r'TP(\\d+) EP\\d+\\] NIXL KVManager initialized with backend: UCX',text)}))
result['pair_warmup_complete']=(live/'pair-warmup.log').exists() and 'ALL 2 P/D paths initialized' in (live/'pair-warmup.log').read_text()
result['connection_http200_count']=sum(' 200 ' in l for l in (live/'connection-warmup.log').read_text().splitlines()) if (live/'connection-warmup.log').exists() else None
result['has_terminal_seal']=(run/'artifact-manifest.json').exists()
result['full_export_present']=(run/'confirm/n52/artifacts/profile_export_aiperf.json').exists()
result['checks']={'submitted_payload_all_match':all(all(x.values()) for x in result['payload'].values()),'execution_same_as_source':all(result['execution_vs_23904'].values()),'server_args_only_random_seed_delta':all(not (set(v['server_args_vs_23904'])-{'random_seed'}) for v in result['runtime'].values()),'mnnvl_flashinfer_nixl_all_eight_ranks':all(result['runtime']['decode-0'][key]==list(range(8)) for key in ['mnnvl_ranks','flashinfer_decode_ranks','nixl_ucx_ranks'])}
(e/'live-runtime-review.json').write_text(json.dumps(result,indent=2)+'\\n')
print(json.dumps({k:result[k] for k in ['checked_utc','checks','runtime','pair_warmup_complete','connection_http200_count','has_terminal_seal','full_export_present']},indent=2))
